function normalizeHub(raw: any): Hub {
  return {
    id: String(raw.id),
    name: String(raw.name ?? 'Untitled Hub'),
    description: String(raw.description ?? ''),
    category: String(raw.category ?? 'Community'),
    icon: String(raw.icon ?? 'people-outline'),
    coverImageUrl: raw.coverImageUrl ?? raw.coverImage ?? null,
    visibility: raw.visibility === 'private' || raw.privacy === 'private' ? 'private' : 'public',
    status: raw.status === 'active' ? 'active' : raw.status === 'archived' ? 'archived' : 'pending',
    membersCount: Number(raw.membersCount ?? raw.memberCount ?? 0),
    postsCount: Number(raw.postsCount ?? raw.postCount ?? 0),
    isMember: Boolean(raw.isMember ?? raw.joined),
    isOwner: Boolean(raw.isOwner ?? raw.role === 'owner'),
    parentHubId: raw.parentHubId === null || raw.parentHubId === undefined
      ? raw.parent?.id ? String(raw.parent.id) : null
      : String(raw.parentHubId),
    createdAt: new Date(raw.createdAt ?? Date.now()).toISOString(),
    updatedAt: new Date(raw.updatedAt ?? raw.createdAt ?? Date.now()).toISOString(),
  };
}

function normalizeHubPost(raw: any): Post {
  const media = Array.isArray(raw.media) ? raw.media : [];
  const firstMedia = media[0];
  const author = raw.author ?? {};
  return {
    id: String(raw.id),
    author: {
      id: String(author.id ?? ''),
      handle: String(author.handle ?? author.username ?? 'user'),
      displayName: String(author.displayName ?? author.name ?? 'Old Time user'),
      bio: String(author.bio ?? ''),
      avatarUrl: author.avatarUrl ?? author.avatarObjectPath ?? null,
      accent: '#f97316',
      followersCount: 0,
      followingCount: 0,
      isFollowing: Boolean(raw.viewer?.followingAuthor),
    },
    mediaUrl: firstMedia?.url ?? firstMedia?.objectPath ?? firstMedia?.uri ?? '',
    mediaType: firstMedia?.type === 'video' ? 'video' : firstMedia ? 'image' : 'quote',
    caption: String(raw.content ?? raw.linkTitle ?? ''),
    location: '',
    likesCount: Number(raw.counts?.likes ?? 0),
    commentsCount: Number(raw.counts?.comments ?? 0),
    likedByMe: Boolean(raw.viewer?.liked),
    createdAt: new Date(raw.createdAt ?? Date.now()).toISOString(),
    comments: [],
  };
}

